from math import gcd
from functools import reduce


def _lattice(points, limit):
    points = sorted(set(points))
    if len(points) < 2:
        return points
    step = reduce(gcd, (b - a for a, b in zip(points, points[1:])))
    first, last = points[0], points[-1]
    while first - step >= 0:
        first -= step
    while last + step < limit:
        last += step
    return list(range(first, last + 1, step))


def transform(grid):
    h, w = len(grid), len(grid[0])
    global_bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Sparse changes occur on repeated horizontal and vertical grid lines.
    # Identify rows whose dominant color differs from the overall wallpaper,
    # then use their changed cells to recover the regular line lattice.
    changed_rows = []
    for r, row in enumerate(grid):
        mode = Counter(row).most_common(1)[0][0]
        if mode != global_bg and any(v != mode for v in row):
            changed_rows.append(r)
    rows = _lattice(changed_rows, h)
    if len(rows) < 2:
        raise ValueError('could not infer horizontal lattice')

    changed_cols = set()
    for r in rows:
        row_mode = Counter(grid[r]).most_common(1)[0][0]
        changed_cols.update(c for c, v in enumerate(grid[r]) if v != row_mode)
    cols = _lattice(changed_cols, w)
    if len(cols) < 2:
        raise ValueError('could not infer vertical lattice')

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        result_row = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = (grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2])
            result_row.append(corners[0] if len(set(corners)) == 1 else global_bg)
        out.append(result_row)
    return out


